/* Practice endpoints: writing (routers/writing.py), speaking (routers/speaking.py),
 * guided listening (routers/comprehension.py), Audio Studio (routers/studio.py) and transcription. */
import { ApiError, apiFetch, getToken } from "./client";

export type ExamTask = "T1" | "T2" | "T3";

/* ---------- Writing ---------- */

export interface WriteTaskSpec {
  id: ExamTask;
  name: string;
  name_en: string;
  desc_en: string;
  min_words: number;
  max_words: number;
  timer_seconds: number;
  part1_range?: string;
  part2_range?: string;
}

/** A built-in subject, or one generated by /api/write/subject. */
export interface WriteSubject {
  id: string;
  title: string;
  prompt: string;
  requirements?: string[];
  doc1?: string;
  doc2?: string;
  stems?: string[];
  words?: string[];
}

export interface WriteFeedback1 {
  word_count?: { actual: number; min: number; max: number; in_range: boolean; note: string };
  checklist?: { point: string; covered: boolean; note: string }[];
  register?: { choice: string; fits: boolean; note: string };
  t3_comparison?: { compared: boolean; position_clear: boolean; note: string } | null;
  praise?: string;
  errors?: { span: string; type: string; hint: string }[];
}

export interface Feedback2 {
  fixed_errors?: { span: string; fixed: boolean; comment: string }[];
  remaining_errors?: { span: string; type: string; hint: string; correction: string }[];
  corrected_text?: string;
  corrected_transcript?: string;
  sentences?: { original: string; corrected: string; explanation: string; chunk: string }[];
  structures?: { french: string; english: string; usage: string }[];
}

export type AttemptStatus = "generating_1" | "generating_2" | "ready" | "failed";

export interface WriteAttempt {
  id: string;
  task: string;
  subject: WriteSubject;
  level: string;
  status: AttemptStatus;
  text_1: string;
  feedback_1: WriteFeedback1;
  text_2: string | null;
  feedback_2: Feedback2;
  seconds: number;
  error: string | null;
  created_at: string;
}

export interface WriteTasks {
  recommended_task: ExamTask;
  recommended_level: string;
  tasks: Record<ExamTask, WriteTaskSpec>;
  subjects: Record<ExamTask, WriteSubject[]>;
  attempts: WriteAttempt[];
}

export const getWriteTasks = () => apiFetch<WriteTasks>("/api/write/tasks");

export const newWriteSubject = (task: ExamTask, level: string, theme = "") =>
  apiFetch<WriteSubject>("/api/write/subject", { body: { task, level: cefr(level), theme } });

export const submitWrite = (task: ExamTask, subject: WriteSubject, level: string, text: string, seconds: number) =>
  apiFetch<WriteAttempt>("/api/write/attempts", { body: { task, subject, level, text, seconds } });

export const submitWriteRound2 = (id: string, text: string, seconds: number) =>
  apiFetch<WriteAttempt>(`/api/write/attempts/${encodeURIComponent(id)}/round2`, { body: { text, seconds } });

export const getWriteAttempt = (id: string) => apiFetch<WriteAttempt>(`/api/write/attempts/${encodeURIComponent(id)}`);

/* ---------- Speaking ---------- */

export interface SpeakTaskSpec {
  id: ExamTask;
  name: string;
  name_en: string;
  desc_en: string;
  timer_seconds: number;
  prep_seconds?: number;
}

export interface SpeakSubject {
  id: string;
  title: string;
  prompt: string;
  questions?: string[];
  role_examiner?: string;
  target_points?: string[];
  structure_hints?: string[];
}

export interface SpeakFeedback1 {
  stats?: { duration_sec: number; wpm: number; pace_note: string };
  checklist?: { point: string; covered: boolean; note: string }[];
  t2_questions?: { count: number; forms_ok: boolean; note: string } | null;
  t3_structure?: { opinion: boolean; arguments: boolean; example: boolean; conclusion: boolean; note: string } | null;
  praise?: string;
  errors?: { span: string; type: string; hint: string }[];
}

export interface SpeakAttempt {
  id: string;
  task: string;
  subject: SpeakSubject;
  status: AttemptStatus;
  transcript_1: string;
  feedback_1: SpeakFeedback1;
  transcript_2: string | null;
  feedback_2: Feedback2;
  error: string | null;
  created_at: string;
}

export interface SpeakTasks {
  recommended_task: ExamTask;
  recommended_level: string;
  tasks: Record<ExamTask, SpeakTaskSpec>;
  subjects: Record<ExamTask, SpeakSubject[]>;
}

export const getSpeakTasks = () => apiFetch<SpeakTasks>("/api/speak/tasks");

export const submitSpeak = (task: ExamTask, subject: SpeakSubject, level: string, transcript: string, seconds: number, audioDuration: number) =>
  apiFetch<SpeakAttempt>("/api/speak/attempts", { body: { task, subject, level, transcript, seconds, audio_duration: audioDuration } });

export const submitSpeakRound2 = (id: string, transcript: string, seconds: number, audioDuration: number) =>
  apiFetch<SpeakAttempt>(`/api/speak/attempts/${encodeURIComponent(id)}/round2`, { body: { transcript, seconds, audio_duration: audioDuration } });

export const getSpeakAttempt = (id: string) => apiFetch<SpeakAttempt>(`/api/speak/attempts/${encodeURIComponent(id)}`);

export interface Turn {
  role: "user" | "assistant";
  content: string;
}

/** The examiner's next line in a Task 2 role-play. `history` excludes the utterance being answered. */
export const roleplayReply = (scenario: SpeakSubject, history: Turn[], utterance: string) =>
  apiFetch<{ reply: string }>("/api/speak/roleplay/reply", { body: { scenario, history, user_utterance: utterance } });

/* ---------- Feedback polling (both writing and speaking run in the background) ---------- */

export const POLL_MS = 3000;
export const MAX_POLLS = 100;

/** Polls until the round's feedback is ready or failed. Rejects with ApiError on 404 or after MAX_POLLS. */
export async function waitForFeedback<T extends { status: AttemptStatus; feedback_1: object; feedback_2: object; error: string | null }>(
  load: () => Promise<T>,
  round: 1 | 2,
  opts: { signal?: AbortSignal; pollMs?: number; maxPolls?: number } = {},
): Promise<T> {
  const pollMs = opts.pollMs ?? POLL_MS;
  const maxPolls = opts.maxPolls ?? MAX_POLLS;
  for (let i = 0; i < maxPolls; i++) {
    await new Promise((r) => setTimeout(r, pollMs));
    if (opts.signal?.aborted) throw new DOMException("Aborted", "AbortError");
    let a: T;
    try {
      a = await load();
    } catch (e) {
      if (e instanceof ApiError && (e.status === 404 || e.status === 401)) throw e;
      continue; // A dropped poll is retried on the next tick.
    }
    if (a.status === "failed") throw new ApiError(502, a.error || "The AI feedback failed. Try again.");
    const fb = round === 1 ? a.feedback_1 : a.feedback_2;
    if (a.status === "ready" && fb && Object.keys(fb).length > 0) return a;
  }
  throw new ApiError(504, "Feedback is taking longer than usual. Check again in a moment — your text is saved.");
}

/* ---------- Guided listening ---------- */

export interface ListeningQuestion {
  prompt: string;
  options: string[];
  answer_index?: number;
  explanation?: string;
}

export interface ListeningSession {
  id: string;
  material: {
    text: string;
    translation_en: string;
    source: string;
    words: { w: string; ipa: string; en: string; note: string }[];
    question: ListeningQuestion;
    breakdown?: string;
  };
  rate: number;
  rate_stage: string;
  blind_plays: number;
  relisten_stages: string[];
  revealed: boolean;
  blind_self: number | null;
  answer_index?: number;
  audio_url_normal: string;
  audio_url_slow: string;
  result?: { correct: boolean };
}

export const newListening = () => apiFetch<ListeningSession>("/api/listening/sessions", { body: { source: "auto" } });
export const getListening = (id: string) => apiFetch<ListeningSession>(`/api/listening/sessions/${encodeURIComponent(id)}`);
const listenAction = (id: string, action: string, body: unknown = {}) =>
  apiFetch<ListeningSession>(`/api/listening/sessions/${encodeURIComponent(id)}/${action}`, { body });
export const listenBlind = (id: string, self: 0 | 1 | 2, plays: number) => listenAction(id, "blind", { self, plays: Math.min(20, Math.max(1, plays)) });
export const listenReveal = (id: string) => listenAction(id, "reveal");
export const listenRelisten = (id: string, index: number) => listenAction(id, "relisten", { stage: index === 0 ? "slow20" : "normal", index });
/** seconds: 0 — the page heartbeat already counts the listening time. */
export const listenCheck = (id: string, answerIndex: number) =>
  listenAction(id, "check", { answer_index: answerIndex, seconds: 0, tz_offset: new Date().getTimezoneOffset() });

/** The relistens done so far; the question unlocks after three (one slow, two normal). */
export const relistensDone = (s: ListeningSession) => s.relisten_stages.length;

/* ---------- Audio Studio ---------- */

export type TransformStyle = "spoken" | "neutral" | "formal" | "polished";
export type TransformLevel = "A1-A2" | "B1-B2" | "C1-C2";

export interface TransformResult {
  text: string;
  task_mode: string;
  task_label: string;
  quality_check: "passed" | "proofread";
}

export const transformToFrench = (text: string, style: TransformStyle, level: TransformLevel, locale: "fr-FR" | "fr-CA") =>
  apiFetch<TransformResult>("/api/transform", { body: { text, style, level, locale, task_mode: "auto" } });

export const VOICES = [
  { id: "fr-FR-DeniseNeural", label: "Denise · France · female" },
  { id: "fr-FR-HenriNeural", label: "Henri · France · male" },
  { id: "fr-FR-VivienneMultilingualNeural", label: "Vivienne · France · female" },
  { id: "fr-FR-RemyMultilingualNeural", label: "Rémy · France · male" },
] as const;

export const makeSpeech = (text: string, voice: string) =>
  apiFetch<{ audio_url: string; srt_url: string; voice: string }>("/api/speech", { body: { text, voice } });

/* ---------- Transcription (local Whisper on the server) ---------- */

/** POSTs a recording as the raw body; returns the French text. */
export async function transcribe(audio: Blob, signal?: AbortSignal): Promise<{ text: string; duration: number }> {
  const headers: Record<string, string> = { Accept: "application/json", "Content-Type": audio.type || "audio/webm" };
  const token = getToken();
  if (token) headers.Authorization = `Bearer ${token}`;
  const res = await fetch("/api/transcribe?language=fr", { method: "POST", headers, body: audio, signal, credentials: "same-origin" });
  let data: { text?: string; duration?: number; detail?: { message?: string } | string } = {};
  try {
    data = await res.json();
  } catch {
    // Non-JSON error page.
  }
  if (!res.ok) {
    const d = data.detail;
    throw new ApiError(res.status, (typeof d === "string" ? d : d?.message) || `Transcription failed (${res.status})`);
  }
  return { text: (data.text ?? "").trim(), duration: data.duration ?? 0 };
}

/* ---------- helpers ---------- */

/** The subject endpoint accepts A1–B2 only. */
function cefr(level: string): string {
  return ["A1", "A2", "B1", "B2"].includes(level) ? level : "A1";
}

export const wordCount = (t: string) => (t.trim() ? t.trim().split(/\s+/).length : 0);
